#include <string>
using namespace std;

class Solution {
public:
    int minDeletionsAlternating(string s) {
        if (s.empty()) return 0;
        int max_alt_len = 1;
        for (int i = 1; i < (int)s.size(); i++) {
            if (s[i] != s[i - 1]) max_alt_len++;
        }
        return (int)s.size() - max_alt_len;
    }
};

class Solution {
    public int minDeletionsAlternating(String s) {
        if (s.isEmpty()) return 0;
        int maxAltLen = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) != s.charAt(i - 1)) maxAltLen++;
        }
        return s.length() - maxAltLen;
    }
}

var minDeletionsAlternating = function(s) {
    if (!s) return 0;
    let maxAltLen = 1;
    for (let i = 1; i < s.length; i++) {
        if (s[i] !== s[i - 1]) maxAltLen++;
    }
    return s.length - maxAltLen;
};
